9:/**
10: * Environment service for accessing environment variables with proper typing.
11: * Replaces the ambient global $env with an explicit, injectable service.
12: */
13:export interface EnvService {
14:  readonly values: Readonly<Record<string, string>>;
15:  get(key: string): string | undefined;
16:  require(key: string): string;
17:  has(key: string): boolean;
18:}
