52:/**
53: * Environment reader for accessing environment variables with proper typing.
54: * Forces callers to handle the absence of values explicitly.
55: */
56:export interface EnvReader {
57:  /** Returns the value or undefined. Callers must handle absence. */
58:  get(key: string): string | undefined;
59:  /** Returns the value or throws. Use when absence is a programming error. */
60:  require(key: string): string;
61:  /** Returns the value or the provided default. */
62:  or(key: string, fallback: string): string;
63:}
