91:/**
92: * The only names that are genuinely unsafe to forward to a native `execve`
93: * spawn: empty, containing `=` (would corrupt the `KEY=VALUE` framing) or
94: * NUL (terminates the C string mid-entry). Windows ships standard variables
95: * whose names contain parentheses (e.g. `ProgramFiles(x86)`, `CommonProgramFiles(x86)`)
96: * — those MUST survive the scrub so downstream resolvers (Git Bash discovery
97: * in `procmgr.ts`, etc.) can still read them.
98: */
99:export function isSafeEnvName(name: string): boolean {
100:	return name.length > 0 && !name.includes("=") && !name.includes("\0");
101:}
