192:/**
193: * Removes {@link GIT_REPO_LOCATION_ENV_NAMES} from a copied child env in place.
194: *
195: * Windows environment lookups are case-insensitive, so a block that spells a
196: * variable `git_dir` is just as binding there; match case-insensitively on
197: * win32 and exactly elsewhere (POSIX env names are case-sensitive).
198: */
199:export function stripGitRepoLocationEnv(
200:	env: Record<string, string>,
201:	platform: NodeJS.Platform = process.platform,
202:): void {
203:	if (platform !== "win32") {
204:		for (const name of GIT_REPO_LOCATION_ENV_NAMES) {
205:			delete env[name];
206:		}
207:		return;
208:	}
209:	const folded = new Set<string>(GIT_REPO_LOCATION_ENV_NAMES.map(name => name.toLowerCase()));
210:	for (const key of Object.keys(env)) {
211:		if (folded.has(key.toLowerCase())) {
212:			delete env[key];
213:		}
214:	}
215:}
