254:function filterChildShellEnvInternal(
255:	env: Record<string, string | undefined>,
256:	cwd: string,
257:	onDotenvValue?: (value: string) => void,
258:): Record<string, string> {
259:	const runtimeLaunchEnvValues = env === Bun.env || env === process.env ? launchEnvValues : undefined;
260:	const result = filterProcessEnv(env);
261:	const projectEnv = parseEnvFile(path.join(cwd, ".env"));
262:	const launchNodeEnv = runtimeLaunchEnvValues ? runtimeLaunchEnvValues.get("NODE_ENV") : env.NODE_ENV;
263:	const nodeEnvName = `.env.${launchNodeEnv || "development"}`;
264:	const modeEnv = parseEnvFile(path.join(cwd, nodeEnvName));
265:	const localEnv = parseEnvFile(path.join(cwd, ".env.local"));
266:	const modeLocalEnv = parseEnvFile(path.join(cwd, `${nodeEnvName}.local`));
267:	const launchEnv = { ...projectEnv, ...modeEnv, ...localEnv, ...modeLocalEnv };
268:	const expandedLaunchEnv = {
269:		...expandDotenvValues(projectEnv, result),
270:		...expandDotenvValues(modeEnv, result),
271:		...expandDotenvValues(localEnv, result),
272:		...expandDotenvValues(modeLocalEnv, result),
273:	};
274:	let fallbackLaunchEnv: Record<string, string> | undefined;
275:	let expandedFallbackLaunchEnv: Record<string, string> | undefined;
276:	if (!runtimeLaunchEnvValues && nodeEnvName !== ".env.development") {
277:		const fallbackModeEnv = parseEnvFile(path.join(cwd, ".env.development"));
278:		const fallbackModeLocalEnv = parseEnvFile(path.join(cwd, ".env.development.local"));
279:		const candidate = { ...projectEnv, ...fallbackModeEnv, ...localEnv, ...fallbackModeLocalEnv };
280:		const expandedCandidate = {
281:			...expandDotenvValues(projectEnv, result),
282:			...expandDotenvValues(fallbackModeEnv, result),
283:			...expandDotenvValues(localEnv, result),
284:			...expandDotenvValues(fallbackModeLocalEnv, result),
285:		};
286:		if (candidate.NODE_ENV === env.NODE_ENV || expandedCandidate.NODE_ENV === env.NODE_ENV) {
287:			// Without a launch snapshot, NODE_ENV may itself have come from dotenv.
288:			// Bun chose the default mode before loading it, so retain both candidates.
289:			fallbackLaunchEnv = candidate;
290:			expandedFallbackLaunchEnv = expandedCandidate;
291:		}
292:	}
293:	const allLaunchEnv = fallbackLaunchEnv ? { ...launchEnv, ...fallbackLaunchEnv } : launchEnv;
294:	if (onDotenvValue) {
295:		// Every value the project's dotenv files define is dotenv-sourced, whether
296:		// or not this process loaded it (a `--cwd` launch never did).
297:		for (const key in allLaunchEnv) onDotenvValue(allLaunchEnv[key]!);
298:		for (const key in expandedLaunchEnv) onDotenvValue(expandedLaunchEnv[key]!);
299:	}
300:	for (const key in allLaunchEnv) {
301:		const launchValue = runtimeLaunchEnvValues?.get(key);
302:		if (launchValue !== undefined) {
303:			// Launcher-owned name: it keeps the launcher's own value. Bun overwrites
304:			// an empty launcher value with the dotenv one, so restore the launcher
305:			// value whenever what survived is exactly what the dotenv file defines.
306:			if (
307:				result[key] !== launchValue &&
308:				(result[key] === launchEnv[key] ||
309:					result[key] === expandedLaunchEnv[key] ||
310:					result[key] === fallbackLaunchEnv?.[key] ||
311:					result[key] === expandedFallbackLaunchEnv?.[key])
312:			) {
313:				result[key] = launchValue;
314:			}
315:			continue;
316:		}
317:		if (runtimeLaunchEnvValues || projectEnvNamesLoadedByOmp.has(key)) {
318:			// Strong provenance: the launch environment is known and this name is
319:			// absent from it, or OMP itself injected the value — either way it came
