321:			const value = result[key];
322:			if (value !== undefined) onDotenvValue?.(value);
323:			delete result[key];
324:		} else if (
325:			result[key] === launchEnv[key] ||
326:			result[key] === expandedLaunchEnv[key] ||
327:			result[key] === fallbackLaunchEnv?.[key] ||
328:			result[key] === expandedFallbackLaunchEnv?.[key]
329:		) {
330:			// No launch-env snapshot (dotenv autoloaded without procfs): best-effort
331:			// value match against the Bun-parsed dotenv.
332:			const value = result[key];
333:			if (value !== undefined) onDotenvValue?.(value);
334:			delete result[key];
335:		}
336:	}
337:	// Last, after dotenv merging: no source (inherited, launcher, or dotenv) may
338:	// pin the child shell to the agent's own repository.
