351:/** Return every value defined by `cwd`'s dotenv files, plus environment values that came from them. */
352:export function getDotenvEnvValues(
353:	cwd: string = getProjectDir(),
354:	env: Record<string, string | undefined> = process.env,
355:): string[] {
356:	const values = new Set<string>();
357:	filterChildShellEnvInternal(env, cwd, value => values.add(value));
