361:/**
362: * Parses a complete .env file with the runtime's dotenv grammar, then retains
363: * only shell-identifier names and spawn-safe values before mirroring valid
364: * `OMP_` variables to their `PI_` aliases.
365: */
366:const __parseEnvFileCache = new Map<string, { mtime: number; data: Record<string, string> }>();
367:
368:export function parseEnvFile(filePath: string): Record<string, string> {
369:	// Memoize on (path, mtime). filterChildShellEnvInternal reads 4 dotenv files per
370:	// child-shell spawn; without this, every subprocess pays 4 synchronous reads.
371:	let mtime = 0;
372:	try {
373:		mtime = statSync(filePath).mtimeMs;
374:	} catch {
375:		/* missing -> empty */
376:	}
377:	const cached = __parseEnvFileCache.get(filePath);
378:	if (cached && cached.mtime === mtime) return cached.data;
379:	const result: Record<string, string> = {};
380:	try {
381:		const parsed = parseEnv(fs.readFileSync(filePath, "utf-8"));
382:		for (const key in parsed) {
383:			const value = parsed[key];
384:			if (
385:				value !== undefined &&
386:				isValidEnvName(key) &&
387:				!isDangerousEnvName(key) &&
388:				!isDotenvForbiddenName(key) &&
389:				isSafeEnvValue(value)
390:			)
391:				result[key] = value;
392:		}
393:	} catch {
394:		// File doesn't exist or can't be read - return empty result
395:	}
396:
397:	// OMP_ overrides PI_
398:	for (const k in result) {
399:		if (k.startsWith("OMP_")) {
400:			result[`PI_${k.slice(4)}`] = result[k];
401:		}
402:	}
403:
404:	__parseEnvFileCache.set(filePath, { mtime, data: result });
405:	return result;
406:}
