409:/**
410: * Intentional re-export of Bun.env.
411: *
412: * All users should import this env module (import { $env } from "@oh-my-pi/pi-utils")
413: * before using environment variables. This ensures that .env files have been loaded and
414: * overrides (project, home) have been applied, so $env always reflects the correct values.
415: */
416:/**
417: * Re-export of Bun.env with undefined-safe indexing.
418: *
419: * Bun.env's runtime type is Record<string, string | undefined>; the historical
420: * export asserted Record<string, string> and every caller assumes string.
421: * Rather than a mass signature change, we proxy the underlying object so
422: * reading an unset name returns "" instead of undefined.
423: */
424:export const $env: Record<string, string> = new Proxy(Bun.env as Record<string, string | undefined>, {
425:	get(target, prop: string) {
426:		const v = target[prop];
427:		return v === undefined ? "" : v;
428:	},
429:}) as Record<string, string>;
