431:/**
432: * Resolve the first environment variable value from the given keys.
433: * @param keys - The keys to resolve.
434: * @returns The first environment variable value, or undefined if no value is found.
435: */
436:export function $pickenv(...keys: string[]): string | undefined {
437:	for (const key of keys) {
438:		const value = Bun.env[key]?.trim();
439:		if (value) {
440:			return value;
441:		}
442:	}
443:	return undefined;
444:}
