446:/**
447: * Read an environment variable by its EXACT, case-sensitive name.
448: *
449: * `process.env` / `Bun.env` lookups are case-insensitive on Windows (Node backs
450: * them with `uv_os_getenv`, Bun with a `CaseInsensitiveASCIIStringArrayHashMap`),
451: * so a lowercase literal like `public` silently resolves to a differently-cased
452: * system variable — Windows ships `PUBLIC=C:\Users\Public`. Enumerated keys are
453: * the only signal that preserves the real casing, so this trusts the lookup only
454: * when a key with identical casing is actually present. On POSIX (case-sensitive
455: * env) it is equivalent to a direct lookup.
456: *
457: * Use this instead of `process.env[name] ?? literal` wherever `name` may be a
458: * user-supplied literal (e.g. a stored API key) rather than a genuine env-var
459: * reference — otherwise the literal gets hijacked by a same-named system var.
460: *
461: * @param name - Environment variable name to look up.
462: * @param env - Environment source; defaults to `process.env`.
463: */
464:export function $envExact(name: string, env: Record<string, string | undefined> = process.env): string | undefined {
465:	const value = env[name];
466:	if (value === undefined) return undefined;
467:	// Enumeration preserves real key casing on Windows, unlike the getter; the
468:	// value is trusted only when an exact-case entry actually exists.
469:	for (const key in env) {
470:		if (key === name) return value;
471:	}
472:	return undefined;
473:}
