475:/**
476: * Parses a positive decimal integer from `$env[name]`.
477: * Empty, invalid, NaN, zero, or negative values return `defaultValue`.
478: */
479:export function $envpos(name: string, defaultValue: number): number {
480:	const raw = $env[name];
481:	if (!raw) return defaultValue;
482:	const parsed = Number.parseInt(raw, 10);
483:	if (Number.isNaN(parsed) || parsed <= 0) return defaultValue;
484:	return parsed;
485:}
