20:/**
21: * Creates an environment service from base values and overlay layers.
22: * Later layers override earlier ones, but never override existing base values
23: * (launcher-owned names keep their launcher value).
24: */
25:export function createEnvService(opts: {
26:  base: Record<string, string | undefined>;
27:  layers: ReadonlyArray<Record<string, string>>;
28:}): EnvService {
29:  const merged: Record<string, string> = {};
30:  // Later layers override earlier ones, but never override existing base values
31:  // (launcher-owned names keep their launcher value).
32:  for (const layer of [...opts.layers].reverse()) {
33:    for (const [k, v] of Object.entries(layer)) {
34:      if (!(k in merged) && opts.base[k] === undefined) merged[k] = v;
35:    }
36:  }
37:  for (const [k, v] of Object.entries(opts.base)) {
38:    if (v !== undefined) merged[k] = v;
39:  }
40:  return Object.freeze({
41:    values: Object.freeze(merged),
42:    get: (k) => merged[k],
43:    require: (k) => {
44:      const v = merged[k];
45:      if (v === undefined) throw new Error(`Missing required env: ${k}`);
46:      return v;
47:    },
48:    has: (k) => k in merged,
49:  });
50:}
