382:/**
383: * Parses a complete .env file with the runtime's dotenv grammar, then retains
384: * only shell-identifier names and spawn-safe values before mirroring valid
385: * `OMP_` variables to their `PI_` aliases.
386: */
387:const __parseEnvFileCache = new Map<string, { mtime: number; data: Record<string, string> }>();
388:
389:export function parseEnvFile(filePath: string): Record<string, string> {
390:	// Memoize on (path, mtime). filterChildShellEnvInternal reads 4 dotenv files per
391:	// child-shell spawn; without this, every subprocess pays 4 synchronous reads.
392:	let mtime = 0;
393:	try {
394:		mtime = statSync(filePath).mtimeMs;
395:	} catch {
396:		/* missing -> empty */
397:	}
398:	const cached = __parseEnvFileCache.get(filePath);
399:	if (cached && cached.mtime === mtime) return cached.data;
400:	const result: Record<string, string> = {};
401:	try {
402:		const parsed = parseEnv(fs.readFileSync(filePath, "utf-8"));
403:		for (const key in parsed) {
404:			const value = parsed[key];
405:			if (
406:				value !== undefined &&
407:				isValidEnvName(key) &&
408:				!isDangerousEnvName(key) &&
409:				!isDotenvForbiddenName(key) &&
410:				isSafeEnvValue(value)
411:			)
412:				result[key] = value;
413:		}
414:	} catch {
415:		// File doesn't exist or can't be read - return empty result
416:	}
417:
418:	// OMP_ overrides PI_
419:	for (const k in result) {
420:		if (k.startsWith("OMP_")) {
421:			result[`PI_${k.slice(4)}`] = result[k];
422:		}
423:	}
424:
425:	__parseEnvFileCache.set(filePath, { mtime, data: result });
426:	return result;
427:}
