467:/**
468: * Read an environment variable by its EXACT, case-sensitive name.
469: *
470: * `process.env` / `Bun.env` lookups are case-insensitive on Windows (Node backs
471: * them with `uv_os_getenv`, Bun with a `CaseInsensitiveASCIIStringArrayHashMap`),
472: * so a lowercase literal like `public` silently resolves to a differently-cased
473: * system variable — Windows ships `PUBLIC=C:\Users\Public`. Enumerated keys are
474: * the only signal that preserves the real casing, so this trusts the lookup only
475: * when a key with identical casing is actually present. On POSIX (case-sensitive
476: * env) it is equivalent to a direct lookup.
477: *
478: * Use this instead of `process.env[name] ?? literal` wherever `name` may be a
479: * user-supplied literal (e.g. a stored API key) rather than a genuine env-var
480: * reference — otherwise the literal gets hijacked by a same-named system var.
481: *
482: * @param name - Environment variable name to look up.
483: * @param env - Environment source; defaults to `process.env`.
484: */
485:export function $envExact(name: string, env: Record<string, string | undefined> = process.env): string | undefined {
486:	const value = env[name];
487:	if (value === undefined) return undefined;
488:	// Enumeration preserves real key casing on Windows, unlike the getter; the
489:	// value is trusted only when an exact-case entry actually exists.
490:	for (const key in env) {
491:		if (key === name) return value;
492:	}
493:	return undefined;
494:}
