498: * Empty, invalid, NaN, zero, or negative values return `defaultValue`.
499: */
500:export function $envpos(name: string, defaultValue: number): number {
501:	const raw = $env[name];
502:	if (!raw) return defaultValue;
503:	const parsed = Number.parseInt(raw, 10);
504:	if (Number.isNaN(parsed) || parsed <= 0) return defaultValue;
505:	return parsed;
