import * as fs from "node:fs";
import { statSync } from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { parseEnv } from "node:util";
import { getAgentDir, getConfigRootDir, getProjectDir, refreshDirsFromEnv } from "./dirs";

export * from "./worker-host";
/**
 * Environment service for accessing environment variables with proper typing.
 * Replaces the ambient global $env with an explicit, injectable service.
 */
export interface EnvService {
  readonly values: Readonly<Record<string, string>>;
  get(key: string): string | undefined;
  require(key: string): string;
  has(key: string): boolean;
}

/**
 * Creates an environment service from base values and overlay layers.
 * Later layers override earlier ones, but never override existing base values
 * (launcher-owned names keep their launcher value).
 */
export function createEnvService(opts: {
  base: Record<string, string | undefined>;
  layers: ReadonlyArray<Record<string, string>>;
}): EnvService {
  const merged: Record<string, string> = {};
  // Later layers override earlier ones, but never override existing base values
  // (launcher-owned names keep their launcher value).
  for (const layer of [...opts.layers].reverse()) {
    for (const [k, v] of Object.entries(layer)) {
      if (!(k in merged) && opts.base[k] === undefined) merged[k] = v;
    }
  }
  for (const [k, v] of Object.entries(opts.base)) {
    if (v !== undefined) merged[k] = v;
  }
    for (const layer of [...opts.layers].reverse()) {
      for (const [k, v] of Object.entries(layer) as [string, string][]) {
        if (!(k in merged) && opts.base[k] === undefined) merged[k] = v;
      }
    }
    for (const [k, v] of Object.entries(opts.base) as [string, string | undefined][]) {
      if (v !== undefined) merged[k] = v;
    }
    require: (k) => {
      const v = merged[k];
      if (v === undefined) throw new Error(`Missing required env: ${k}`);
      return v;
    },
    has: (k) => k in merged,
  });
}

/**
 * Environment reader for accessing environment variables with proper typing.
 * Forces callers to handle the absence of values explicitly.
 */
export interface EnvReader {
  /** Returns the value or undefined. Callers must handle absence. */
  get(key: string): string | undefined;
  /** Returns the value or throws. Use when absence is a programming error. */
  require(key: string): string;
  /** Returns the value or the provided default. */
  or(key: string, fallback: string): string;
}

/**
 * Creates an environment reader from a source.
 */
export function createEnvReader(source: Record<string, string | undefined>): EnvReader {
  return {
    get: (k) => source[k],
    require: (k) => {
      const v = source[k];
      if (v === undefined) throw new Error(`Missing required environment variable: ${k}`);
      return v;
    },
    or: (k, fallback) => source[k] ?? fallback,
  };
}

const ENV_NAME_RE = /^[A-Za-z_][A-Za-z0-9_]*$/;

/**
 * Strict shell-identifier shape. Used for dotenv keys we accept into
 * `Bun.env` — those should be referenceable as `$NAME` from POSIX shells,
 * so we reject anything outside `[A-Za-z_][A-Za-z0-9_]*`.
 */
export function isValidEnvName(name: string): boolean {
	return ENV_NAME_RE.test(name);
}

/**
 * The only names that are genuinely unsafe to forward to a native `execve`
 * spawn: empty, containing `=` (would corrupt the `KEY=VALUE` framing) or
 * NUL (terminates the C string mid-entry). Windows ships standard variables
 * whose names contain parentheses (e.g. `ProgramFiles(x86)`, `CommonProgramFiles(x86)`)
 * — those MUST survive the scrub so downstream resolvers (Git Bash discovery
 * in `procmgr.ts`, etc.) can still read them.
 */
export function isSafeEnvName(name: string): boolean {
	return name.length > 0 && !name.includes("=") && !name.includes("\0");
}

export function isSafeEnvValue(value: string): boolean {
	return !value.includes("\0");
}

export function isMacosMallocStackLoggingEnvName(name: string): boolean {
	return name === "MallocStackLogging" || name === "MallocStackLoggingNoCompact";
}

/**
 * True when running inside a WSL (Windows Subsystem for Linux) distribution.
 *
 * WSL reports `linux` for `process.platform`, so the only reliable signal is
 * the `WSL_DISTRO_NAME`/`WSL_INTEROP` variables the interop layer injects.
 * Callers use this to translate Windows drive paths to their `/mnt/<drive>`
 * mounts and to route clipboard access through `powershell.exe`.
 */
export function isWsl(platform: NodeJS.Platform = process.platform, env: NodeJS.ProcessEnv = process.env): boolean {
	return platform === "linux" && Boolean(env.WSL_DISTRO_NAME || env.WSL_INTEROP);
}

// [tau-fix] dangerous env denylist
const DANGEROUS_ENV_NAMES = new Set<string>([
	"NODE_OPTIONS",
	"NODE_PATH",
	"BUN_INSPECT",
	"BUN_OPTIONS",
	"LD_PRELOAD",
	"LD_LIBRARY_PATH",
	"DYLD_INSERT_LIBRARIES",
	"DYLD_LIBRARY_PATH",
	"PYTHONSTARTUP",
	"PYTHONPATH",
	"PYTHONHOME",
	"PERL5OPT",
	"PERL5LIB",
	"RUBYOPT",
	"RUBYLIB",
	"JAVA_TOOL_OPTIONS",
	"_JAVA_OPTIONS",
	"GIT_CONFIG_GLOBAL",
	"GIT_CONFIG_SYSTEM",
	"SSH_AUTH_SOCK",
	"SSH_AGENT_PID",
]);
const DOTENV_FORBIDDEN_NAMES = new Set<string>(["PATH"]);
export function isDotenvForbiddenName(name: string): boolean {
	if (DOTENV_FORBIDDEN_NAMES.has(name)) return true;
	return process.platform === "win32" && DOTENV_FORBIDDEN_NAMES.has(name.toUpperCase());
}

export function isDangerousEnvName(name: string): boolean {
	if (DANGEROUS_ENV_NAMES.has(name)) return true;
	return process.platform === "win32" && DANGEROUS_ENV_NAMES.has(name.toUpperCase());
