384:	// Memoize on (path, mtime). filterChildShellEnvInternal reads 4 dotenv files per
385:	// child-shell spawn; without this, every subprocess pays 4 synchronous reads.
386:	let mtime = 0;
387:	try {
388:		mtime = statSync(filePath).mtimeMs;
389:	} catch {
390:		/* missing -> empty */
391:	}
392:	const cached = __parseEnvFileCache.get(filePath);
393:	if (cached && cached.mtime === mtime) return cached.data;
394:	const result: Record<string, string> = {};
395:	try {
396:		const parsed = parseEnv(fs.readFileSync(filePath, "utf-8"));
397:		for (const key in parsed) {
398:			const value = parsed[key];
399:			if (
400:				value !== undefined &&
401:				isValidEnvName(key) &&
402:				!isDangerousEnvName(key) &&
403:				!isDotenvForbiddenName(key) &&
404:				isSafeEnvValue(value)
405:			)
406:				result[key] = value;
407:		}
408:	} catch {
409:		// File doesn't exist or can't be read - return empty result
410:	}
411:
412:	// OMP_ overrides PI_
413:	for (const k in result) {
414:		if (k.startsWith("OMP_")) {
415:			result[`PI_${k.slice(4)}`] = result[k];
416:		}
417:	}
418:
419:	__parseEnvFileCache.set(filePath, { mtime, data: result });
420:	return result;
421:}
