424:/**
425: * Intentional re-export of Bun.env.
426: *
427: * All users should import this env module (import { $env } from "@oh-my-pi/pi-utils")
428: * before using environment variables. This ensures that .env files have been loaded and
429: * overrides (project, home) have been applied, so $env always reflects the correct values.
430: */
431:/**
432: * Re-export of Bun.env with undefined-safe indexing.
433: *
434: * Bun.env's runtime type is Record<string, string | undefined>; the historical
435: * export asserted Record<string, string> and every caller assumes string.
436: * Rather than a mass signature change, we proxy the underlying object so
437: * reading an unset name returns "" instead of undefined.
438: */
439:export const $env: Record<string, string> = new Proxy(Bun.env as Record<string, string | undefined>, {
440:	get(target, prop: string) {
441:		const v = target[prop];
442:		return v === undefined ? "" : v;
443:	},
444:}) as Record<string, string>;
