446:/**
447: * Resolve the first environment variable value from the given keys.
448: * @param keys - The keys to resolve.
449: * @returns The first environment variable value, or undefined if no value is found.
450: */
451:export function $pickenv(...keys: string[]): string | undefined {
452:	for (const key of keys) {
453:		const value = Bun.env[key]?.trim();
454:		if (value) {
455:			return value;
456:		}
457:	}
458:	return undefined;
459:}
