461:/**
462: * Read an environment variable by its EXACT, case-sensitive name.
463: *
464: * `process.env` / `Bun.env` lookups are case-insensitive on Windows (Node backs
465: * them with `uv_os_getenv`, Bun with a `CaseInsensitiveASCIIStringArrayHashMap`),
466: * so a lowercase literal like `public` silently resolves to a differently-cased
467: * system variable — Windows ships `PUBLIC=C:\Users\Public`. Enumerated keys are
468: * the only signal that preserves the real casing, so this trusts the lookup only
469: * when a key with identical casing is actually present. On POSIX (case-sensitive
470: * env) it is equivalent to a direct lookup.
471: *
472: * Use this instead of `process.env[name] ?? literal` wherever `name` may be a
473: * user-supplied literal (e.g. a stored API key) rather than a genuine env-var
474: * reference — otherwise the literal gets hijacked by a same-named system var.
475: *
476: * @param name - Environment variable name to look up.
477: * @param env - Environment source; defaults to `process.env`.
478: */
479:export function $envExact(name: string, env: Record<string, string | undefined> = process.env): string | undefined {
480:	const value = env[name];
481:	if (value === undefined) return undefined;
482:	// Enumeration preserves real key casing on Windows, unlike the getter; the
483:	// value is trusted only when an exact-case entry actually exists.
484:	for (const key in env) {
485:		if (key === name) return value;
486:	}
487:	return undefined;
488:}
