490:/**
491: * Parses a positive decimal integer from `$env[name]`.
492: * Empty, invalid, NaN, zero, or negative values return `defaultValue`.
493: */
494:export function $envpos(name: string, defaultValue: number): number {
495:	const raw = $env[name];
496:	if (!raw) return defaultValue;
497:	const parsed = Number.parseInt(raw, 10);
498:	if (Number.isNaN(parsed) || parsed <= 0) return defaultValue;
499:	return parsed;
500:}
