describe("Escaped-dollar unescaping", () => {
  it("does not expand escaped dollar signs in .env files", () => {
    // Create a temporary directory with a .env file
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "pi-utils-env-test-"));
    const envFilePath = path.join(dir, ".env");
    // Set an environment variable
    const varName = "TEST_VAR";
    const varValue = "actual-value";
    process.env[varName] = varValue;
    try {
      // Write .env file with escaped and unescaped references
      fs.writeFileSync(
        envFilePath,
        [
          `ESCAPED=\\$${varName}`,
          `UNESCAPED=$${varName}`,
          `OTHER=value`,
        ].join("\n"),
      );
      // Call filterChildShellEnv with the directory containing the .env file
