describe("Escaped-dollar unescaping", () => {
  it("does not expand escaped dollar signs in .env files", () => {
    // Create a temporary directory with a .env file
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "pi-utils-env-test-"));
    const envFilePath = path.join(dir, ".env");
    // Set an environment variable
    const varName = "TEST_VAR";
    const varValue = "actual-value";
    process.env[varName] = varValue;
    try {
      // Write .env file with escaped and unescaped references
      fs.writeFileSync(
        envFilePath,
        [
          `ESCAPED=\\$${varName}`,
          `UNESCAPED=$${varName}`,
          `OTHER=value`,
        ].join("\n"),
      );
      // Call filterChildShellEnv with the directory containing the .env file
      const result = filterChildShellEnv({}, dir);
      // The escaped variable should not be expanded
      expect(result.ESCAPED).toBe(`\\$${varName}`);
      // The unescaped variable should be expanded to the environment variable value
      expect(result.UNESCAPED).toBe(varValue);
      // Other variable should be present
      expect(result.OTHER).toBe("value");
    } finally {
      delete process.env[varName];
      // Clean up the temporary directory
      const tmpDirs = [dir];
      for (const d of tmpDirs) {
        try {
          fs.rmSync(d, { recursive: true, force: true });
        } catch {
          // Ignore errors during cleanup
        }
      }
    }
  });
});

