416:export function parseEnvFile(filePath: string): Record<string, string> {
417:	// Memoize on (path, mtime). filterChildShellEnvInternal reads 4 dotenv files per
418:	// child-shell spawn; without this, every subprocess pays 4 synchronous reads.
419:	let mtime = 0;
420:	try {
421:		mtime = statSync(filePath).mtimeMs;
422:	} catch {
423:		/* missing -> empty */
424:	}
425:	const cached = __parseEnvFileCache.get(filePath);
426:	if (cached && cached.mtime === mtime) return cached.data;
427:	const result: Record<string, string> = {};
428:	try {
429:		const parsed = parseEnv(fs.readFileSync(filePath, "utf-8"));
430:		for (const key in parsed) {
431:			const value = parsed[key];
432:			if (
433:				value !== undefined &&
434:				isValidEnvName(key) &&
435:				!isDangerousEnvName(key) &&
