494:/**
495: * Read an environment variable by its EXACT, case-sensitive name.
496: *
497: * `process.env` / `Bun.env` lookups are case-insensitive on Windows (Node backs
498: * them with `uv_os_getenv`, Bun with a `CaseInsensitiveASCIIStringArrayHashMap`),
499: * so a lowercase literal like `public` silently resolves to a differently-cased
500: * system variable — Windows ships `PUBLIC=C:\Users\Public`. Enumerated keys are
501: * the only signal that preserves the real casing, so this trusts the lookup only
502: * when a key with identical casing is actually present. On POSIX (case-sensitive
503: * env) it is equivalent to a direct lookup.
504: *
505: * Use this instead of `process.env[name] ?? literal` wherever `name` may be a
506: * user-supplied literal (e.g. a stored API key) rather than a genuine env-var
507: * reference — otherwise the literal gets hijacked by a same-named system var.
508: *
509: * @param name - Environment variable name to look up.
510: * @param env - Environment source; defaults to `process.env`.
511: */
512:export function $envExact(name: string, env: Record<string, string | undefined> = process.env): string | undefined {
513:	const value = env[name];
514:	if (value === undefined) return undefined;
515:	// Enumeration preserves real key casing on Windows, unlike the getter; the
516:	// value is trusted only when an exact-case entry actually exists.
517:	for (const key in env) {
518:		if (key === name) return value;
519:	}
520:	return undefined;
521:}
